'use client';

import { useEffect } from 'react';
import { createPortal } from 'react-dom';
import { ScrollText, X } from 'lucide-react';
import styles from './auth.module.css';

interface TermsModalProps {
  open: boolean;
  onClose: () => void;
  onAccept: () => void;
}

const RULES = [
  'Use the Bureau training files for your own learning. Do not share your credentials with other cadets.',
  'Your progress, answers and hint usage are logged to personalise your training and track case completion.',
  'Exercises may be generated by an AI assistant; treat its explanations as guidance, not gospel.',
  'Keep conduct respectful. Attempts to tamper with case files, scores or other accounts will revoke clearance.',
  'You can request that your personnel file be closed and your data removed at any time.',
];

/** Bureau Field Rules & Terms of Service, rendered in a portal above the locked auth page. */
export default function TermsModal({ open, onClose, onAccept }: TermsModalProps) {
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  if (!open || typeof document === 'undefined') return null;

  return createPortal(
    <div className={styles.modalOverlay} onClick={onClose}>
      <div
        className={styles.modal}
        role="dialog"
        aria-modal="true"
        aria-labelledby="terms-title"
        onClick={(e) => e.stopPropagation()}
      >
        <div className={styles.modalHead}>
          <h2 id="terms-title" className={styles.modalTitle}>
            <ScrollText size={16} aria-hidden /> BUREAU FIELD RULES &amp; TERMS OF SERVICE
          </h2>
          <button type="button" className={styles.modalClose} onClick={onClose} aria-label="Close terms">
            <X size={16} aria-hidden />
          </button>
        </div>

        <ol className={styles.modalList}>
          {RULES.map((rule) => <li key={rule}>{rule}</li>)}
        </ol>

        <p className={styles.tip}>Read it twice, Cadet — the fine print hides the best clues. — Inspector Crit</p>

        <div className={styles.modalActions}>
          <button type="button" className={styles.modalSecondary} onClick={onClose}>Close</button>
          <button type="button" className={styles.btn} onClick={() => { onAccept(); onClose(); }}>
            I Agree
          </button>
        </div>
      </div>
    </div>,
    document.body,
  );
}
